- Периодическая очистка записей с истёкшим TTL (иначе set растёт).

Код:

```js
const revoked = new Map(); // jti -> expiresAt

function revoke(jti, exp) {
  revoked.set(jti, exp * 1000);
}

function isRevoked(jti) {
  const exp = revoked.get(jti);
  if (exp === undefined) return false;
  if (exp < Date.now()) { revoked.delete(jti); return false; }
  return true;
}
```

