```python
import base64, hmac, hashlib, json, time

def _b64d(s):
    s += "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s)

def validate_token(token, secret):
    try:
        h, p, sig = token.split(".")
    except ValueError:
        return None
    if json.loads(_b64d(h)).get("alg") != "HS256":
        return None
    expected = hmac.new(secret, f"{h}.{p}".encode(),
                        hashlib.sha256).digest()
    if not hmac.compare_digest(expected, _b64d(sig)):
        return None
    claims = json.loads(_b64d(p))
    now = int(time.time())
    if claims.get("exp", 0) < now or claims.get("iat", now + 1) > now:
        return None
    return {"sub": claims.get("sub"), "role": claims.get("role")}
```

